"                        {orderType === 'DELIVERY' || (orderType === 'PICKUP' && subOrderType === 'DELIVERY') ? (
                          <button
                            onClick={() => {
                              setIsRiderModalOpen(true);
                            }}
                            className={`shrink-0 transition-colors relative ${selectedRiderId ? 'text-emerald-500 hover:text-emerald-400' : (isDark ? 'text-gray-300 hover:text-white' : 'text-slate-800 hover:text-black')}`}
                            title={selectedRiderId ? `Rider: ${riders.find(r => String(r.id) === String(selectedRiderId))?.name || 'Rider'}` : "Select Delivery Boy"}
                          >
                            <Bike size={18} strokeWidth={2.5} />
                            {selectedRiderId && (
                              <span className="absolute -top-1 -right-1 w-2 h-2 bg-emerald-500 rounded-full" />
                            )}
                          </button>
                        ) : (
                          <button
                            onClick={() => {
                              setIsWaiterModalOpen(true);
                            }}
                            className={`shrink-0 transition-colors relative ${selectedWaiter ? 'text-emerald-500 hover:text-emerald-400' : (isDark ? 'text-gray-300 hover:text-white' : 'text-slate-800 hover:text-black')}`}
                            title={selectedWaiter ? `Waiter: ${selectedWaiter.name}` : "Select Waiter"}
                          >
                            <svg viewBox="0 0 24 24" width="18" height="18" stroke="currentColor" strokeWidth="2.5" fill="none">
                              <path d="M3 20h18" strokeLinecap="round" />
                              <path d="M19 16a7 7 0 0 0-14 0z" fill={selectedWaiter ? 'currentColor' : 'none'} />
                              <path d="M12 5v4M10 5h4" strokeLinecap="round" />
                            </svg>

